#!/bin/bash
set -euo pipefail
Q=/srv/opentallas-scratch2/claude; R=/srv/opentallas-scratch2/claude/die-qc34; C=/srv/opentallas-scratch2/claude/codex-qc-import-0824; M=$Q/codex-qc-mesh5-1029; B=$Q/codex-qc-1029/baseline26; PC=$Q/codex-qc-provider-clock-0834
mkdir -p $R/prebuild_d1_nobackbone
docker run --rm --name dqc35-d1-$$ --memory=64g --memory-swap=64g --cpus=4 -v "$Q:$Q" -w "$R" python:3.12 bash -c "set -e; trap \"chown -R 1000:1000 $R/prebuild_d1_nobackbone\" EXIT; pip -q install shapely numpy pyyaml jsonschema >/dev/null 2>&1; cd $R/src_pc/tools/clk; python fixed_tree_provider.py --base-adapter $M/src/results/qc_clock_physical_1029/fixed_tree.py --repo $R/src_pc --provider-clock-loads $PC/access2_jointpg/clock_loads_access.json --provider-bindings $Q/qc-import-1/bound/bindings.json --provider-via-facts $M/census119_h800/probe_census.json --native-clock-landings $Q/die-qc29/formA/census_full/landing_plan.json --phy-clock-stubs $Q/die-qc30/b1/phy_stub_plan.json --tree $B/trial26/clock/tree.json --netlist $C/reachfix/mechanics/clkonly.v --lef $Q/codex-qc-physical-1029/inputs/cells.lef --plan $Q/qc-import-1/plan/plan_qc_import1.json --endpoints $C/reachfix/mechanics/endpoints.json --tech-vias $M/census119_h800/probe_census.json --out $R/prebuild_d1_nobackbone > $R/prebuild_d1_nobackbone/run.log 2>&1"
tail -20 $R/prebuild_d1_nobackbone/run.log
